#include <stdio.h>
#include <stdlib.h>

#define MOD 1000000007LL
#define NEG_INF (-(1LL << 60))

typedef struct {
    long long a, b;
} Aff;

static int cmp_spell(const void *p, const void *q) {
    const Aff *x = (const Aff *)p;
    const Aff *y = (const Aff *)q;

    if (x->a < y->a) return -1;
    if (x->a > y->a) return 1;

    if (x->b > y->b) return -1;
    if (x->b < y->b) return 1;

    return 0;
}

static int cmp_meal(const void *p, const void *q) {
    const Aff *x = (const Aff *)p;
    const Aff *y = (const Aff *)q;

    if (x->a == 1 || y->a == 1) {
        if (x->a == 1 && y->a == 1) return 0;
        if (x->a == 1) return -1;
        return 1;
    }

    long long lhs = x->b * (y->a - 1);
    long long rhs = y->b * (x->a - 1);

    if (lhs > rhs) return -1;
    if (lhs < rhs) return 1;
    return 0;
}

static long long ceil_div(long long p, long long den) {
    if (p >= 0) return (p + den - 1) / den;
    return p / den;
}

static long long mod_pow(long long base, long long exp) {
    base %= MOD;
    long long res = 1;

    while (exp > 0) {
        if (exp & 1LL) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1LL;
    }

    return res;
}

static long long mod_inv(long long x) {
    return mod_pow(x, MOD - 2);
}

int main(void) {
    int N, M;
    long long K;

    if (scanf("%d %d %lld", &N, &M, &K) != 3) return 0;

    Aff *spells = (Aff *)malloc((size_t)N * sizeof(Aff));
    long long *tmpA = (long long *)malloc((size_t)N * sizeof(long long));

    for (int i = 0; i < N; i++) {
        scanf("%lld", &tmpA[i]);
    }

    long long maxA = -1, maxB = -1;

    for (int i = 0; i < N; i++) {
        long long b;
        scanf("%lld", &b);

        spells[i].a = tmpA[i];
        spells[i].b = b;

        if (tmpA[i] > maxA || (tmpA[i] == maxA && b > maxB)) {
            maxA = tmpA[i];
            maxB = b;
        }
    }

    free(tmpA);

    Aff *meals = (Aff *)malloc((size_t)M * sizeof(Aff));
    long long *tmpM = (long long *)malloc((size_t)M * sizeof(long long));

    for (int i = 0; i < M; i++) {
        scanf("%lld", &tmpM[i]);
    }

    for (int i = 0; i < M; i++) {
        long long b;
        scanf("%lld", &b);

        meals[i].a = tmpM[i];
        meals[i].b = b;
    }

    free(tmpM);

    qsort(meals, (size_t)M, sizeof(Aff), cmp_meal);

    long long mealA = 1, mealB = 0;

    for (int i = 0; i < M; i++) {
        long long a = meals[i].a % MOD;
        long long b = meals[i].b % MOD;

        mealB = (a * mealB + b) % MOD;
        mealA = (mealA * a) % MOD;
    }

    qsort(spells, (size_t)N, sizeof(Aff), cmp_spell);

    long long *ha = (long long *)malloc((size_t)N * sizeof(long long));
    long long *hb = (long long *)malloc((size_t)N * sizeof(long long));
    long long *hstart = (long long *)malloc((size_t)N * sizeof(long long));

    int S = 0;
    long long lastA = -1;

    for (int i = 0; i < N; i++) {
        if (spells[i].a == lastA) continue;

        lastA = spells[i].a;

        long long a = spells[i].a;
        long long b = spells[i].b;

        while (S > 0) {
            long long den = a - ha[S - 1];
            long long p = hb[S - 1] - b;
            long long s = ceil_div(p, den);

            if (s <= hstart[S - 1]) {
                S--;
            } else {
                break;
            }
        }

        if (S == 0) {
            hstart[S] = NEG_INF;
        } else {
            long long den = a - ha[S - 1];
            long long p = hb[S - 1] - b;
            hstart[S] = ceil_div(p, den);
        }

        ha[S] = a;
        hb[S] = b;
        S++;
    }

    int Q;
    scanf("%d", &Q);

    long long q = K - 1;

    for (int qi = 0; qi < Q; qi++) {
        long long x;
        scanf("%lld", &x);

        int lo = 0, hi = S - 1, ans = 0;

        while (lo <= hi) {
            int mid = (lo + hi) >> 1;

            if (hstart[mid] <= x) {
                ans = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }

        long long val = ha[ans] * x + hb[ans];
        long long y1 = val % MOD;

        long long y;

        if (maxA == 1) {
            long long add = (q % MOD) * (maxB % MOD) % MOD;
            y = (y1 + add) % MOD;
        } else {
            long long powA = mod_pow(maxA % MOD, q);
            long long inv = mod_inv(maxA - 1);

            long long term = (maxB % MOD) * ((powA - 1 + MOD) % MOD) % MOD;
            term = term * inv % MOD;

            y = (powA * y1 + term) % MOD;
        }

        long long answer = (mealA * y + mealB) % MOD;

        printf("%lld\n", answer);
    }

    free(spells);
    free(meals);
    free(ha);
    free(hb);
    free(hstart);

    return 0;
}
